/**
 * NOUN General Studies e-Courseware — hosted on ZikShare.
 *
 * These are real PDFs. They live in `public/library/gst/` and download from
 * ZikShare like any other library document; nothing here points at another
 * site. The catalogue is generated by `scripts/build-gst-shelf.mjs`, which
 * measures every file and checks each title against the text inside it, so no
 * card can claim a page count or a title the document does not have.
 *
 * ## Rights
 *
 * The documents are published by the National Open University of Nigeria in its
 * public e-Courseware repository. NOUN's own notice on that repository permits
 * educational use and prohibits commercial use. ZikShare charges nothing for
 * them, names NOUN on every card, and links back to the source page. It does
 * not claim authorship of any of them.
 */
import { GST_SHELF } from './gstLibraryData'

export const GST_DOMAIN = 'GST & Compulsory Courses'
export const ENTREPRENEURSHIP_DOMAIN = 'Money & Career'

export const NOUN_SOURCE = {
    name: 'National Open University of Nigeria',
    page: 'https://nou.edu.ng/ecourseware-degs/',
    note: 'NOUN publishes this courseware in its public e-Courseware repository and permits educational use; it prohibits commercial use. ZikShare hosts it free, charges nothing and names NOUN on every card.',
}

/** Which shelf a course sits on: the GST courses, or the entrepreneurship set. */
export function shelfFor(code) {
    return code.startsWith('NEE') ? ENTREPRENEURSHIP_DOMAIN : GST_DOMAIN
}

/**
 * Shape the library UI renders. Unlike the Greek plays, these are hosted: the
 * card carries a real `download_path` and a measured page count.
 */
export function toGstCard(item) {
    return {
        id: `gst-${item.code.toLowerCase()}`,
        slug: item.slug,
        code: item.codeLabel,
        title: `${item.codeLabel}: ${item.title}`,
        subtitle: item.about,
        author: 'National Open University of Nigeria',
        publisher: NOUN_SOURCE.name,
        faculty: 'General Studies (GST / CED)',
        department: item.code.startsWith('NEE') ? 'Entrepreneurship' : 'General Studies',
        level: item.level,
        semester: item.semester,
        material_type: 'textbooks',
        subcategory: 'textbooks',
        domain: shelfFor(item.code),
        priceKobo: 0,
        is_free: true,
        page_count: item.pages,
        file_size_bytes: item.bytes,
        description: item.about,
        // The whole point: a ZikShare URL, not a link to someone else's site.
        download_path: item.download_path,
        storage_path: null,
        source_url: NOUN_SOURCE.page,
        source_note: NOUN_SOURCE.note,
        unizik_note: item.unizik,
        sha256: item.sha256,
        is_official: true,
        isGst: true,
        isExternal: false,
        isBook: false,
        isFresherPdf: false,
    }
}

export const GST_CARDS = GST_SHELF.map(toGstCard)

export const GST_COURSES = GST_CARDS.filter((card) => card.domain === GST_DOMAIN)
export const ENTREPRENEURSHIP_COURSES = GST_CARDS.filter((card) => card.domain === ENTREPRENEURSHIP_DOMAIN)

/** Totals for the page copy, derived from the shelf rather than typed. */
export function gstTotals() {
    const pages = GST_SHELF.reduce((total, item) => total + item.pages, 0)
    const bytes = GST_SHELF.reduce((total, item) => total + item.bytes, 0)
    return { documents: GST_SHELF.length, pages, megabytes: Math.round((bytes / 1048576) * 10) / 10 }
}

export function findGstCard(slug) {
    return GST_CARDS.find((card) => card.slug === slug) || null
}
